const cfg = $item(0).$node['Config'].json;

function parseCsv(text) {
  const rows = [];
  let row = [];
  let cell = '';
  let inQuotes = false;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    const next = text[i + 1];
    if (inQuotes) {
      if (ch === '"' && next === '"') { cell += '"'; i++; }
      else if (ch === '"') { inQuotes = false; }
      else { cell += ch; }
    } else {
      if (ch === '"') inQuotes = true;
      else if (ch === ',') { row.push(cell); cell = ''; }
      else if (ch === '\n') { row.push(cell); rows.push(row); row = []; cell = ''; }
      else if (ch === '\r') { }
      else { cell += ch; }
    }
  }
  if (cell.length || row.length) { row.push(cell); rows.push(row); }
  return rows;
}

async function doHttpRequest(options) {
  if (typeof $httpRequest === 'function') return await $httpRequest(options);
  if (this?.helpers?.httpRequest) return await this.helpers.httpRequest(options);
  throw new Error('HTTP helper not available');
}

function rowsToObjects(rows) {
  if (!rows.length) return [];
  const headers = rows[0].map((h) => String(h || '').trim());
  const out = [];
  for (let i = 1; i < rows.length; i++) {
    const r = rows[i];
    const obj = {};
    headers.forEach((h, idx) => { if (h) obj[h] = r[idx] ?? ''; });
    const hasAnyValue = Object.values(obj).some((v) => String(v || '').trim() !== '');
    if (hasAnyValue) out.push(obj);
  }
  return out;
}

let records = [];
const sourceType = String(cfg.sourceType || 'google_sheet').toLowerCase();

if (sourceType === 'google_sheet') {
  if (!cfg.sheetId) throw new Error('Config.sheetId is required for google_sheet sourceType');

  const sheetName = String(cfg.sheetName || '').trim();
  const sheetGid = String(cfg.sheetGid || '').trim();

  const urls = [];
  if (sheetName) urls.push(`https://docs.google.com/spreadsheets/d/${cfg.sheetId}/gviz/tq?tqx=out:csv&sheet=${encodeURIComponent(sheetName)}`);
  if (sheetGid) urls.push(`https://docs.google.com/spreadsheets/d/${cfg.sheetId}/export?format=csv&gid=${encodeURIComponent(sheetGid)}`);
  urls.push(`https://docs.google.com/spreadsheets/d/${cfg.sheetId}/export?format=csv`);

  let csvText = null;
  let lastErr = null;
  for (const url of urls) {
    try {
      const r = await doHttpRequest.call(this, { method: 'GET', url, json: false, headers: { Accept: 'text/csv' } });
      csvText = typeof r === 'string' ? r : String(r || '');
      if (csvText && csvText.trim()) break;
    } catch (e) {
      lastErr = e;
    }
  }

  if (!csvText) throw new Error(`Unable to fetch CSV from Google Sheets. Last error: ${lastErr?.message || 'unknown'}`);
  const rows = parseCsv(csvText);
  records = rowsToObjects(rows);
} else if (sourceType === 'static_json') {
  let arr = [];
  try {
    arr = JSON.parse(String(cfg.staticRecordsJson || '[]'));
  } catch (e) {
    throw new Error('Config.staticRecordsJson is not valid JSON');
  }
  records = Array.isArray(arr) ? arr : [arr];
} else {
  throw new Error(`Unsupported sourceType: ${sourceType}`);
}

if (!records.length) throw new Error('No records loaded from configured source');

return records.map((r) => ({ json: { source: cfg.sourceLabel || 'apollo_sheet_import', raw_payload: r, ...r } }));

