const sql=`INSERT INTO "Apollo_Contacts" (${cols.map(c=>`"${c}"`).join(', ')}, "ingested_at", "updated_at")\nVALUES (${values.join(', ')}, NOW(), NOW())\nON CONFLICT (apollo_contact_id) DO UPDATE SET\n${updates.join(',\n')};`;
